<?php
require $argv[1].'/src/marketing/Growth.php';use FAS\Marketing\Growth;
$out=[];
foreach(['email-replace','stop-resave'] as $mode){$i=new PDO('sqlite::memory:');$i->exec(file_get_contents($argv[1].'/tests/fixtures/applepay-schema.sql'));$g=new Growth(new PDO('sqlite::memory:'),$i,['url'=>'https://example.invalid'],fn()=>1800000000);$owner=str_repeat('o',64);$g->saveCart($owner,'old@example.invalid',[['id'=>1,'quantity'=>1]],false);if($mode==='stop-resave')$g->stopCart($owner);$g->saveCart($owner,$mode==='email-replace'?'new@example.invalid':'old@example.invalid',[['id'=>2,'quantity'=>1]],false);$cart=$g->run('SELECT email,status FROM growth_carts')->fetch();$msgs=$g->run('SELECT email,status,dedupe FROM growth_messages')->fetchAll();if(count($msgs)!==2||$msgs[0]['status']!=='cancelled'||$msgs[1]['status']!=='queued')throw new RuntimeException('New generation reminder missing');$row=$g->run("SELECT email,payload,dedupe FROM growth_messages WHERE status='queued'")->fetch();$generation=$g->run('SELECT email,restore_hash,unsubscribe_hash FROM growth_carts')->fetch();$payload=json_decode($row['payload'],true);if($row['email']!==$generation['email']||hash('sha256',$payload['restore'])!==$generation['restore_hash']||hash('sha256',$payload['unsubscribe'])!==$generation['unsubscribe_hash']||$row['dedupe']!=='reminder:1:'.$generation['restore_hash'])throw new RuntimeException('Queued reminder generation mismatch');$g->updateCart($owner,[['id'=>2,'quantity'=>2]]);if((int)$g->run('SELECT COUNT(*) FROM growth_messages')->fetchColumn()!==2)throw new RuntimeException('Heartbeat duplicated reminder');$out[]=['case'=>$mode,'cart'=>$cart,'messages'=>$msgs,'current_generation_queued_count'=>(int)$g->run("SELECT COUNT(*) FROM growth_messages WHERE status='queued'")->fetchColumn()];}echo json_encode($out,JSON_PRETTY_PRINT);
